module.exports = function (Messaging) {
	Messaging.editMessage = async (uid, mid, roomId, content) => {
		if (!await Messaging.messageExists(mid)) {
			throw new Error('[[error:invalid-mid]]');
		}
		const rawMessage = await Messaging.getMessageFields(mid, ['content', 'roomId']);
		if (!rawMessage || String(rawMessage.roomId) !== String(roomId)) {
			throw new Error('[[error:invalid-mid]]');
